import { useEffect, useMemo, useState } from 'react';
import { createProject, getProjects } from './api';
import './projects.css';

function Projects({ search = '', userRole }) {
	const [projects, setProjects] = useState([]);
	const [projectName, setProjectName] = useState('');
	const [description, setDescription] = useState('');
	const [isLoading, setIsLoading] = useState(true);
	const [error, setError] = useState('');

	useEffect(() => {
		getProjects()
			.then((response) => setProjects(response.data))
			.catch((loadError) => setError(loadError.message))
			.finally(() => setIsLoading(false));
	}, []);

	const visibleProjects = useMemo(() => {
		const query = search.toLowerCase();
		return projects.filter((project) => !query || `${project.name} ${project.description}`.toLowerCase().includes(query));
	}, [projects, search]);

	async function handleSubmit(event) {
		event.preventDefault();
		setError('');
		try {
			const response = await createProject({ name: projectName, description });
			setProjects((currentProjects) => [response.data, ...currentProjects]);
			setProjectName('');
			setDescription('');
		} catch (submitError) {
			setError(submitError.message);
		}
	}

	return (
		<section className="projects-page" aria-labelledby="projects-title">
			<div className="projects-heading">
				<div><p className="dashboard-label">Workspace planning</p><h2 id="projects-title">Projects</h2><p>Organize related tasks into focused workstreams.</p></div>
				<span className="project-count"><strong>{projects.length}</strong> projects</span>
			</div>

			{userRole !== 'User' && <form className="project-create-form" onSubmit={handleSubmit}><div><label htmlFor="project-name">Project name</label><input id="project-name" value={projectName} onChange={(event) => setProjectName(event.target.value)} placeholder="e.g. Website launch" maxLength="80" required /></div><div><label htmlFor="project-description">Description</label><input id="project-description" value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What is this project about?" /></div><button type="submit">Create project</button></form>}
			{error && <p className="project-error" role="alert">{error}</p>}
			{isLoading && <p className="project-empty">Loading projects...</p>}
			{!isLoading && !error && visibleProjects.length === 0 && <p className="project-empty">No projects found.</p>}
			{!isLoading && <div className="project-board-shell">
				{visibleProjects.map((project, projectIndex) => {
					const memberCount = project.members?.length || 0;
					const boardTasks = [
						{ title: project.name || `Project ${projectIndex + 1}`, assignee: project.owner?.fullname || 'user1', type: 'Standard', priority: 'Medium', status: 'In progress', timeline: 'Apr 12 - May 15', budget: '$200,000.00', cost: '$200,000.00' },
						{ title: project.description || 'Project review', assignee: 'user1', type: 'Internal', priority: 'Low', status: 'Pending', timeline: 'Apr 12 - May 15', budget: '$200,000.00', cost: '$200,000.00' },
					];

					return (
						<section className="project-board" key={project._id || projectIndex}>
							<div className="project-board-header">
								<div className="project-board-title-wrap">
									<span className="project-board-bullet" aria-hidden="true" />
									<h3>{project.name}</h3>
								</div>
								<span className="project-board-count">{memberCount}</span>
							</div>

							<div className="project-board-grid project-board-grid-head">
								<span>Assignee</span>
								<span>Subtasks</span>
								<span>Task Type</span>
								<span>Priority</span>
								<span>Status</span>
								<span>Timeline</span>
								<span>Budget</span>
								<span>Cost</span>
							</div>

							{boardTasks.map((task, idx) => (
								<div className="project-board-grid project-board-row" key={`${project._id || projectIndex}-${idx}`}>
									<div className="project-task-name"><span>{task.title}</span></div>
									<div className="project-cell project-assignee">{task.assignee}</div>
									<div className="project-cell project-type">{task.type}</div>
									<div className="project-cell project-priority"><span className={`project-pill project-pill-${task.priority.toLowerCase().replace(/\s+/g, '-')}`}>{task.priority}</span></div>
									<div className="project-cell project-status"><span className={`project-pill project-pill-${task.status.toLowerCase().replace(/\s+/g, '-')}`}>{task.status}</span></div>
									<div className="project-cell project-date">{task.timeline}</div>
									<div className="project-cell project-budget">{task.budget}</div>
									<div className="project-cell project-cost">{task.cost}</div>
								</div>
							))}
							<button type="button" className="project-add-task">Add Task</button>
						</section>
					);
				})}
			</div>}
		</section>
	);
}

export default Projects;
